def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    out = [row[:] for row in grid]

    colors = set(x for row in grid for x in row) - {bg}
    # Main shapes are the large regions; small isolated colors are noise or markers.
    boxes = {}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if len(cells) >= 4:
            boxes[color] = (min(r for r, c in cells), max(r for r, c in cells),
                            min(c for r, c in cells), max(c for r, c in cells))

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color in boxes:
                continue
            matches = [k for k, (r0, r1, c0, c1) in boxes.items()
                       if r0 <= r <= r1 and c0 <= c <= c1]
            out[r][c] = matches[0] if len(matches) == 1 else bg
    return out
